import * as zod from "zod";

export const SkillResource = zod.strictObject({
  authoredByAssistant: zod
    .boolean()
    .describe(
      "True when the assistant wrote this skill during a conversation rather than a person\nwriting it here.\n\nWhich conversation is deliberately not returned: skills are shared across the project\nwhile conversations belong to one person, so naming one would tell everybody in the\nproject that a particular colleague had it.",
    ),
  description: zod
    .string()
    .describe(
      "Why the assistant would open this skill. It sits in every request, so it is the one field worth writing carefully.",
    ),
  enabled: zod.boolean(),
  files: zod
    .record(zod.string(), zod.string())
    .nullish()
    .describe(
      "Path to contents, `SKILL.md` among them. Only returned by `get-skill`; the list leaves it out.",
    ),
  name: zod.string(),
  origin: zod
    .enum(["builtin", "project"])
    .describe(
      "`builtin` — provided by the platform and read-only here.\n`project` — written for this project and editable by anyone in it.",
    ),
  shortDescription: zod.string().nullable(),
  updatedAt: zod.iso
    .datetime({ offset: true })
    .nullable()
    .describe("Null for built-in skills, which have no edit history here."),
});

export type SkillResource = zod.input<typeof SkillResource>;
export type SkillResourceOutput = zod.output<typeof SkillResource>;
